      const questions=texts.filter(n=>{const s=(original.get(n)||n.nodeValue).trim();return s.endsWith('?')&&!/^(What will you study|What are they|What are Front-Mu points|What are the Four Seas|What are Window of Heaven points|What is a Meeting Point|Why is this correct|Why are the other)/.test(s)});
