  spanish.addEventListener('click',e=>{e.stopImmediatePropagation();e.preventDefault();student.click();active=true;nativeRun++;requestAnimationFrame(()=>{[...bar.querySelectorAll('button')].forEach(b=>b.setAttribute('aria-pressed',String(b===spanish)));document.body.classList.add('student-preview');translate();const s=bar.querySelector('[role=status]');if(s)s.textContent='Vista del estudiante en español — traduciendo el contenido abierto…';setTimeout(()=>translateUnmapped(root),0)})},true);
